<div class="page-heading"><div><span class="eyebrow">Agenda</span><h1>Citas</h1><p>Programación de pacientes y profesionales.</p></div><button class="btn btn-primary" data-modal-open="appt-create">＋ Cita</button></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><section class="card"><div class="table-wrap"><table class="modern-table"><thead><tr><th>Inicio</th><th>Paciente</th><th>Profesional</th><th>Estado</th><th>Motivo</th></tr></thead><tbody><?php foreach($appointments as $a):?><tr><td><?=e($a['fecha_inicio'])?></td><td><?=e($a['paciente'])?></td><td><?=e($a['profesional']??'—')?></td><td><?=e($a['estado'])?></td><td><?=e($a['motivo']??'')?></td></tr><?php endforeach;?></tbody></table></div></section><div class="modal" id="appt-create"><div class="modal-backdrop"></div><div class="modal-dialog modal-lg"><div class="modal-header"><h2>Nueva cita</h2><button class="modal-close" data-modal-close>×</button></div><form method="POST" action="<?=url('/citas')?>"><?=csrf_field()?><div class="modal-body form-grid"><label><span>Paciente</span><select name="animal_id"><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['nombre'])?></option><?php endforeach;?></select></label><label><span>Profesional</span><select name="profesional_id"><option value="">Sin asignar</option><?php foreach($professionals as $u):?><option value="<?=$u['id']?>"><?=e($u['nombres'].' '.$u['apellidos'])?></option><?php endforeach;?></select></label><label><span>Estado</span><select name="estado_cita_id"><?php foreach($statuses as $s):?><option value="<?=$s['id']?>"><?=e($s['nombre'])?></option><?php endforeach;?></select></label><label><span>Inicio</span><input type="datetime-local" name="fecha_inicio" required></label><label><span>Fin</span><input type="datetime-local" name="fecha_fin"></label><label><span>Motivo</span><input name="motivo"></label></div><div class="modal-footer"><button class="btn btn-primary">Guardar</button></div></form></div></div>
